-- Generated tests table for storing test code generated alongside fixes
-- These tests verify that fixes work correctly and prevent regressions

CREATE TABLE generated_tests (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    incident_id UUID NOT NULL REFERENCES incidents(id) ON DELETE CASCADE,
    -- Suggested test file path (e.g., "src/user.test.ts")
    file_path TEXT NOT NULL,
    -- The test source code
    content TEXT NOT NULL,
    -- Description of what the test verifies
    description TEXT,
    -- Test framework used (e.g., "jest", "pytest", "go test")
    framework TEXT NOT NULL,
    -- Whether the test was included in the PR
    included_in_pr BOOLEAN DEFAULT false,
    -- SHA of the commit that included this test (if any)
    commit_sha TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX idx_generated_tests_incident ON generated_tests(incident_id);
CREATE INDEX idx_generated_tests_framework ON generated_tests(framework);

-- Add a column to incidents to track if tests were generated
ALTER TABLE incidents ADD COLUMN IF NOT EXISTS tests_generated BOOLEAN DEFAULT false;
ALTER TABLE incidents ADD COLUMN IF NOT EXISTS test_count INT DEFAULT 0;

COMMENT ON TABLE generated_tests IS 'Unit tests automatically generated by CRISPR to verify fixes';
COMMENT ON COLUMN generated_tests.file_path IS 'Suggested path for the test file following language conventions';
COMMENT ON COLUMN generated_tests.content IS 'Complete test source code, ready to be committed';
COMMENT ON COLUMN generated_tests.framework IS 'Test framework (jest, pytest, go test, etc.)';
